import{c as s,Q as a,j as i,m as e}from"./chunks/framework.BXc4yaFE.js";const g=JSON.parse('{"title":"Loop Prompt Engineering: A New Approach to Optimizing Prompts","description":"","frontmatter":{"url":"https://x.com/leanxbt/status/2070852461494202609","title":"Loop Prompt Engineering: A New Approach to Optimizing Prompts","author":"leanxbt","archived":"2026-07-03T00:00:00.000Z","handle":"@leanxbt","published":"2026-06-27T00:00:00.000Z","stats":"73 likes · 8 retweets · 158 bookmarks · 77269 views","tags":["loop-engineering","prompt-optimization","eval-design","reward-hacking","plateau-detector"],"type":"twitter-article"},"headers":[],"relativePath":"research/tweets/2026-06-27-@leanxbt-202609.md","filePath":"research/tweets/2026-06-27-@leanxbt-202609.md","lastUpdated":1785909234000}'),n={name:"research/tweets/2026-06-27-@leanxbt-202609.md"};function o(l,t,r,p,h,d){return a(),i("div",null,[...t[0]||(t[0]=[e(`<h1 id="loop-prompt-engineering-a-new-approach-to-optimizing-prompts-—-leanxbt" tabindex="-1">Loop Prompt Engineering: A New Approach to Optimizing Prompts — @leanxbt <a class="header-anchor" href="#loop-prompt-engineering-a-new-approach-to-optimizing-prompts-—-leanxbt" aria-label="Permalink to &quot;Loop Prompt Engineering: A New Approach to Optimizing Prompts — @leanxbt&quot;">​</a></h1><p><strong>來源</strong>：<a href="https://x.com/leanxbt/status/2070852461494202609" target="_blank" rel="noreferrer">https://x.com/leanxbt/status/2070852461494202609</a><strong>作者</strong>：leanxbt（@leanxbt） <strong>發布日期</strong>：2026-06-27 <strong>收錄日期</strong>：2026-07-03 <strong>類型</strong>：Twitter Article <strong>統計</strong>：73 likes · 8 retweets · 158 bookmarks · 77269 views</p><hr><h2 id="全文摘要" tabindex="-1">全文摘要 <a class="header-anchor" href="#全文摘要" aria-label="Permalink to &quot;全文摘要&quot;">​</a></h2><p><strong>定位</strong>：將 Loop Engineering 應用於 prompt 自動優化：用評估集的數字作為成功條件，讓 agent 根據失敗案例自動改寫 prompt，直到達到閾值。完整 Python 實作，含防作弊機制。</p><h3 id="核心概念" tabindex="-1">核心概念 <a class="header-anchor" href="#核心概念" aria-label="Permalink to &quot;核心概念&quot;">​</a></h3><p><strong>Prompt 優化循環</strong>：loop 重寫 prompt → 針對評估集運行 → 評分 → 重複，直到分數高於閾值。Agent 讀取失敗案例後診斷並改寫 prompt。</p><h3 id="評估集可靠性等級-從高到低" tabindex="-1">評估集可靠性等級（從高到低） <a class="header-anchor" href="#評估集可靠性等級-從高到低" aria-label="Permalink to &quot;評估集可靠性等級（從高到低）&quot;">​</a></h3><ol><li><strong>Exact match / regex</strong>：最可靠</li><li><strong>Classification</strong>：固定標籤比對</li><li><strong>Verifiable property</strong>：JSON 解析、數字範圍、程式碼測試</li><li><strong>Judge-model 評分</strong>：最後手段，因無硬性錨點</li></ol><blockquote><p>規則：把任務盡量推向等級 1/2。每往下一層都引入噪音，讓 loop 可以作弊的空間更大。</p></blockquote><h3 id="三種作弊方式-reward-hacking" tabindex="-1">三種作弊方式（Reward Hacking） <a class="header-anchor" href="#三種作弊方式-reward-hacking" aria-label="Permalink to &quot;三種作弊方式（Reward Hacking）&quot;">​</a></h3><p><strong>1. Overfitting（過擬合評估集）</strong></p><ul><li>症狀：訓練分數 0.95，但真實場景崩潰</li><li>修復：<strong>train/holdout 分割</strong>，成功條件只看 holdout，不看 train</li></ul><p><strong>2. Judge-model 自我讚美（Self-praise Collusion）</strong></p><ul><li>症狀：judge 和 worker 是同一模型 → agent 學習讓 judge 喜歡的風格而非正確答案</li><li>修復：<strong>judge 用不同模型</strong>；judge prompt 要有事實錨點（expected answer），不純評「品質」</li></ul><p><strong>3. Metric Gaming</strong></p><ul><li>症狀：優化 exact match → 模型只答一個詞；優化長度 → 答案膨脹</li><li>修復：<strong>多維度評估</strong>（準確度 + 長度懲罰），讓不同方向互相拉扯</li></ul><h3 id="propose-函數設計-強版本" tabindex="-1">Propose 函數設計（強版本） <a class="header-anchor" href="#propose-函數設計-強版本" aria-label="Permalink to &quot;Propose 函數設計（強版本）&quot;">​</a></h3><div class="language-python vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">python</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">def</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> propose</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(current_prompt, fails, call_model):</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    meta_prompt </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> f</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;&quot;&quot;You are optimizing a prompt. Here is the current prompt:</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&lt;current_prompt&gt;</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">{</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">current_prompt</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">}</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&lt;/current_prompt&gt;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">It failed on these examples:</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">{</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">fail_text</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">}</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">First, in one or two sentences, diagnose the SINGLE most common reason</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">these failed. Then rewrite the prompt to fix that reason specifically.</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">Rules:</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">- Keep what already works, change only what addresses the diagnosed failure.</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">- Do not add instructions that target these exact inputs by content.</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  Generalize the fix, do not memorize the examples.</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">- Output ONLY the new prompt, nothing else.&quot;&quot;&quot;</span></span></code></pre></div><p><strong>關鍵</strong>：Agent 先給出「單一診斷」再改寫，防止每次修補全部問題導致 prompt 膨脹成矛盾指令堆。</p><h3 id="成本控制-plateau-detector-高原偵測器" tabindex="-1">成本控制：Plateau Detector（高原偵測器） <a class="header-anchor" href="#成本控制-plateau-detector-高原偵測器" aria-label="Permalink to &quot;成本控制：Plateau Detector（高原偵測器）&quot;">​</a></h3><div class="language-python vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">python</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">PATIENCE</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 3</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">  # N 次迭代無改善即停止</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 主迴圈中：</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">if</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> best[</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;score&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">] </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> prev_best </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">+</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 0.005</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    no_improve </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">+=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 1</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    if</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> no_improve </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> PATIENCE</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">        print</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Plateau for N iterations. Burning money for nothing.&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">); </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">break</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">else</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    no_improve </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 0</span></span></code></pre></div><p><strong>Plateau detector 比 iteration cap 更重要</strong>：Prompt 優化通常快速拿到容易的百分點後停滯，10 次迭代固守 0.88 卻每次都消耗整個評估集。PATIENCE 在無改善時立即停止。</p><h3 id="_4-種-loop-死亡模式" tabindex="-1">4 種 Loop 死亡模式 <a class="header-anchor" href="#_4-種-loop-死亡模式" aria-label="Permalink to &quot;4 種 Loop 死亡模式&quot;">​</a></h3><ol><li><strong>Runaway</strong>：呼叫計數攀升但 holdout 不動。閾值設定不切實際（baseline 0.5 → target 0.99 不可達）</li><li><strong>Silent death by overfit（最危險）</strong>：train 分數慢慢上升但 holdout 未動。只看 train 分數的成功條件</li><li><strong>Random walk</strong>：score 在同一點抖動不收斂。propose 只改外表，或 temperature 過高</li><li><strong>Comprehension debt（最隱晦）</strong>：loop 交付 holdout 0.93 的 prompt，你部署後卻不理解它為何有效 → 過擬合評估集的 prompt 在真實生產上崩潰</li></ol><h3 id="適用場景" tabindex="-1">適用場景 <a class="header-anchor" href="#適用場景" aria-label="Permalink to &quot;適用場景&quot;">​</a></h3><p><strong>值得建</strong>：prompt 在生產環境頻繁運行（分類器/提取器/路由器），有標記評估集或容易收集，品質可量化為數字。</p><p><strong>不值得建</strong>：只跑一兩次的一次性創意 prompt → 建評估集的成本無法被使用頻率攤還。</p><h3 id="核心原則-與-the-loop-一致" tabindex="-1">核心原則（與 The Loop 一致） <a class="header-anchor" href="#核心原則-與-the-loop-一致" aria-label="Permalink to &quot;核心原則（與 The Loop 一致）&quot;">​</a></h3><blockquote><p><strong>「A loop is exactly as good as the part it cannot touch. Build that untouchable part first, and the optimization second.」</strong></p></blockquote><p>→ 把判斷帶到外部（holdout 評估集 + 事實錨點），agent 無法重寫的部分越可靠，loop 越可信。</p><hr><h2 id="研究摘要" tabindex="-1">研究摘要 <a class="header-anchor" href="#研究摘要" aria-label="Permalink to &quot;研究摘要&quot;">​</a></h2><p><strong>TL;DR</strong>：Loop Engineering 應用於 prompt 自動優化：eval 可靠性等級、train/holdout 防過擬合、judge 異模型防自我讚美、PATIENCE 高原偵測器防空燒、診斷優先改寫、Comprehension debt 警告。技術深度最高，適用於高頻生產 prompt 優化場景。</p><h3 id="核心論點" tabindex="-1">核心論點 <a class="header-anchor" href="#核心論點" aria-label="Permalink to &quot;核心論點&quot;">​</a></h3><ul><li><strong>Eval 硬化優先於優化</strong>：先把評估從主觀推向可量化，再建 loop</li><li><strong>PATIENCE 高原偵測器</strong>：比 iteration cap 更重要的成本控制機制，在無改善時停止</li><li><strong>診斷優先改寫</strong>：agent 給出「單一診斷」後才改寫，防 prompt 無限膨脹</li><li><strong>Comprehension debt</strong>：部署自己看不懂的 loop 輸出 = 過擬合未發覺</li></ul><h3 id="關鍵數據-工具" tabindex="-1">關鍵數據 / 工具 <a class="header-anchor" href="#關鍵數據-工具" aria-label="Permalink to &quot;關鍵數據 / 工具&quot;">​</a></h3><ul><li>完整 Python 實作（evaluate, optimize, propose, history 全部提供）</li><li>PATIENCE = 3（3 次無改善即停，高原早停閾值 0.005）</li><li>評估等級：exact match → label → verifiable → judge-model</li><li><code>.champion.json</code>：只在 holdout 分數真正提升時覆蓋</li></ul><h3 id="批判性觀察" tabindex="-1">批判性觀察 <a class="header-anchor" href="#批判性觀察" aria-label="Permalink to &quot;批判性觀察&quot;">​</a></h3><ul><li>不是 Fable 5 特定內容；適用於任何 LLM 的 prompt 優化</li><li>PATIENCE 高原偵測器可作為 /goal loop 設計原則（N 次無改善即停）</li><li>Comprehension debt 概念對 unverified_success 閘門是有價值的補充</li><li>文章比其他批次 Fable 5 文章更具技術深度和代碼品質</li><li>使用場景限於高頻生產 prompt，對一般工作區規則整合性有限</li></ul><hr><h2 id="評分" tabindex="-1">評分 <a class="header-anchor" href="#評分" aria-label="Permalink to &quot;評分&quot;">​</a></h2><table tabindex="0"><thead><tr><th>維度</th><th>分數</th><th>說明</th></tr></thead><tbody><tr><td>A. Workspace 可行動性 (30%)</td><td>5/10</td><td>PATIENCE 概念和 Comprehension debt 有工作區價值；整體適用場景較窄</td></tr><tr><td>B. 創新性 (20%)</td><td>8/10</td><td>將 Loop Engineering 應用於 prompt 自動優化是完整創新框架；三種作弊防禦全面</td></tr><tr><td>C. 證據品質 (20%)</td><td>7/10</td><td>完整工作 Python 代碼；4 種死亡模式有具體症狀；無定量成本數據</td></tr><tr><td>D. 技術深度 (15%)</td><td>9/10</td><td>Eval 設計/judge 設計/記憶歷史/成本控制完整技術棧，最深之一</td></tr><tr><td>E. 泛化性 (15%)</td><td>7/10</td><td>生產高頻 prompt 場景廣泛；評估集概念跨語言跨模型</td></tr><tr><td><strong>加權總分</strong></td><td><strong>6.9/10</strong></td><td>5×0.3+8×0.2+7×0.2+9×0.15+7×0.15</td></tr></tbody></table><p><strong>整合決策</strong>：Others <strong>理由</strong>：技術上高品質但主要適用於「生產環境高頻 prompt 優化」這個特定場景；PATIENCE 高原偵測器可作參考但不足以單獨整合；Comprehension debt 概念已在 workspace 的 unverified_success 閘門中有對應覆蓋。</p>`,44)])])}const c=s(n,[["render",o]]);export{g as __pageData,c as default};
